/** Decode base64 into the flat grayscale array a Signature expects. */
function unpack(data: string): number[] {
  const binary = atob(data);
  const out = new Array<number>(binary.length);
  for (let i = 0; i < binary.length; i++) out[i] = binary.charCodeAt(i);
  return out;
}

let cached: GlyphTemplate[] | null = null;

/** Built-in templates, decoded once on first use. */
export function builtInTemplates(): GlyphTemplate[] {
  if (!cached) {
    cached = PACKED.map(t => ({
      rank: t.rank,
      suit: t.suit,
      signature: { w: GLYPH_W, h: GLYPH_H, data: unpack(t.data) },
    }));
  }
  return cached;
}

